result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "src/laborders/service.py", "content": """"OrderService: the only way the DB and journal are ever mutated.

Mutation protocol (order matters!):

    BEGIN IMMEDIATE            -- serialize writers
    SELECT current status      -- authoritative check *inside* the txn
    if check fails: ROLLBACK, raise IllegalTransition (journal untouched)
    journal.append(...)        -- fsync FIRST: intent is now durable
    UPDATE orders ...          -- then the DB write
    COMMIT

Crash simulation: `skip_db_write=True` performs steps 1-4 but skips the
UPDATE/COMMIT, leaving a durable journal record with no matching DB
state — precisely the state a crash between fsync and commit produces,
and exactly what recover() repairs.
"""

from __future__ import annotations

import os
import sqlite3
import threading
import uuid

from .journal import Journal
from .model import (
    LEGAL_TRANSITIONS,
    JournalCorruption,
    OrderError,
    IllegalTransition,
    UnknownOrder,
)
from .store import connect


class OrderService:
    def __init__(self, db_path: str | os.PathLike[str],
                 journal_path: str | os.PathLike[str]):
        self.db_path = os.fspath(db_path)
        self.journal = Journal(journal_path)
        self._local = threading.local()

    # -- connection management (one per thread => concurrency-safe) ------

    def _conn(self) -> sqlite3.Connection:
        conn = getattr(self._local, "conn", None)
        if conn is None:
            conn = connect(self.db_path)
            self._local.conn = conn
        return conn

    def close(self) -> None:
        conn = getattr(self._local, "conn", None)
        if conn is not None:
            conn.close()
            self._local.conn = None
        self.journal.close()

    # -- reads -------------------------------------------------------------

    def get(self, order_id: str) -> dict | None:
        row = self._conn().execute(
            "SELECT id, patient, test_code, status, updated_at "
            "FROM orders WHERE id = ?", (order_id,)
        ).fetchone()
        return dict(row) if row else None

    # -- mutations -----------------------------------------------------------

    def create(self, patient: str, test_code: str,
               *, skip_db_write: bool = False) -> dict:
        """Create a new order in status 'draft'."""
        order_id = uuid.uuid4().hex[:12]
        conn = self._conn()
        conn.execute("BEGIN IMMEDIATE")
        try:
            entry = self.journal.append(
                op="create", order_id=order_id, frm=None, to="draft",
            )
            if not skip_db_write:
                conn.execute(
                    "INSERT INTO orders (id, patient, test_code, status, updated_at) "
                    "VALUES (?, ?, ?, 'draft', ?)",
                    (order_id, patient, test_code, entry["ts"]),
                )
            conn.execute("COMMIT")
        except BaseException:
            conn.execute("ROLLBACK")
            raise
        return {"id": order_id, "patient": patient,
                "test_code": test_code, "status": "draft",
                "updated_at": entry["ts"]}

    def transition(self, order_id: str, to: str,
                   *, skip_db_write: bool = False) -> dict:
        """Move an order to `to`, enforcing the legal-transition matrix.

        The status check happens INSIDE a BEGIN IMMEDIATE transaction,
        so concurrent attempts to move the same order are serialized:
        exactly one winner, all losers see the post-write state and are
        rejected cleanly.
        """
        conn = self._conn()
        conn.execute("BEGIN IMMEDIATE")
        try:
            row = conn.execute(
                "SELECT status FROM orders WHERE id = ?", (order_id,)
            ).fetchone()
            if row is None:
                raise UnknownOrder(order_id)
            frm = row["status"]
            if (frm, to) not in LEGAL_TRANSITIONS:
                raise IllegalTransition(order_id, frm, to)

            entry = self.journal.append(
                op="transition", order_id=order_id, frm=frm, to=to,
            )

            if not skip_db_write:
                cur = conn.execute(
                    "UPDATE orders SET status = ?, updated_at = ? "
                    "WHERE id = ? AND status = ?",
                    (to, entry["ts"], order_id, frm),
                )
                if cur.rowcount != 1:  # pragma: no cover - guarded by IMMEDIATE lock
                    raise OrderError(f"concurrent update lost for {order_id}")
            conn.execute("COMMIT")
        except BaseException:
            conn.execute("ROLLBACK")
            raise
        return self.get(order_id)

    # Convenience verbs ------------------------------------------------------

    def sign(self, order_id: str, **kw) -> dict:
        return self.transition(order_id, "signed", **kw)

    def collect(self, order_id: str, **kw) -> dict:
        return self.transition(order_id, "collected", **kw)

    def result(self, order_id: str, **kw) -> dict:
        return self.transition(order_id, "resulted", **kw)

    def cancel(self, order_id: str, **kw) -> dict:
        return self.transition(order_id, "cancelled", **kw)

    # -- recovery --------------------------------------------------------------

    def recover(self) -> dict:
        """Replay journal entries missing from the DB. Idempotent.

        Rules per entry, evaluated in journal order:
          create     : INSERT if the order is absent, else skip.
          transition : skip if DB already at entry['to'];
                       apply if DB is at entry['from'];
                       otherwise the journal contradicts the DB -> error.
        """
        replayed = skipped = 0
        conn = self._conn()
        for entry in self.journal.entries():
            oid = entry["order_id"]
            if entry["op"] == "create":
                if conn.execute(
                    "SELECT 1 FROM orders WHERE id = ?", (oid,)
                ).fetchone():
                    skipped += 1
                    continue
                if entry["to"] != "draft":
                    raise JournalCorruption(f"seq {entry['seq']}: create to {entry['to']!r}")
                conn.execute(
                    "INSERT INTO orders (id, patient, test_code, status, updated_at) "
                    "VALUES (?, '<recovered>', '<recovered>', ?, ?)",
                    (oid, entry["to"], entry["ts"]),
                )
                replayed += 1
                continue

            row = conn.execute(
                "SELECT status FROM orders WHERE id = ?", (oid,)
            ).fetchone()
            if row is None:
                raise JournalCorruption(
                    f"seq {entry['seq']}: transition for unknown order {oid}"
                )
            status = row["status"]
            if status == entry["to"]:
                skipped += 1          # already applied -> idempotent no-op
                continue
            if status != entry["from"]:
                raise JournalCorruption(
                    f"seq {entry['seq']}: journal says {entry['from']!r} -> "
                    f"{entry['to']!r} but DB has {status!r}"
                )
            conn.execute(
                "UPDATE orders SET status = ?, updated_at = ? WHERE id = ?",
                (entry["to"], entry["ts"], oid),
            )
            replayed += 1
        return {"replayed": replayed, "skipped": skipped}

    # -- audit: rebuild history from the journal alone --------------------------

    def history(self, order_id: str) -> list[dict]:
        """Reconstruct one order's full history from journal lines only.

        Validates that the chain of entries is internally consistent
        (starts with create; every subsequent entry's 'from' equals the
        previous entry's 'to'). Touches the database zero times.
        """
        chain = [e for e in self.journal.entries() if e["order_id"] == order_id]
        if not chain:
            raise UnknownOrder(order_id)
        first = chain[0]
        if first["op"] != "create":
            raise JournalCorruption(f"order {oid_str(order_id)}: history does not start with create")
        prev = first["to"]
        for entry in chain[1:]:
            if entry["from"] != prev or entry["op"] != "transition":
                raise JournalCorruption(
                    f"order {oid_str(order_id)} seq {entry['seq']}: broken chain"
                )
            prev = entry["to"]
        return [{"seq": e["seq"], "op": e["op"], "from": e["from"],
                 "to": e["to"], "ts": e["ts"]} for e in chain]


def oid_str(oid: str) -> str:  # tiny helper keeps f-strings readable above
    return repr(oid)
